function render(ctx) {
  const p = ctx.parameters;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const number = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const rawColor = typeof p.marker_color === 'string' ? p.marker_color.trim() : '';
  let markerColor = '#C9822B';
  if (/^#[0-9a-f]{3}$/i.test(rawColor)) {
    markerColor = ('#' + rawColor[1] + rawColor[1] + rawColor[2] + rawColor[2] + rawColor[3] + rawColor[3]).toUpperCase();
  } else if (/^#[0-9a-f]{6}$/i.test(rawColor)) {
    markerColor = rawColor.toUpperCase();
  } else {
    const rgbMatch = rawColor.match(/^rgba?\(([^)]+)\)$/i);
    if (rgbMatch) {
      const values = rgbMatch[1].split(',').slice(0, 3).map((part) => {
        const n = parseFloat(part);
        if (!Number.isFinite(n)) return 0;
        return part.indexOf('%') >= 0 ? n * 2.55 : n;
      });
      markerColor = '#' + values.map((v) => clamp(Math.round(v), 0, 255).toString(16).padStart(2, '0')).join('').toUpperCase();
    }
  }
  const settleFrames = Math.max(0, number(p.title_settle_frames, 20));
  const delayFrames = Math.max(0, number(p.marker_start_delay_frames, 6));
  const drawFrames = Math.max(1, number(p.marker_draw_frames, 10));
  const startFrame = settleFrames + delayFrames;
  if (ctx.frame < startFrame) return [];
  const progress = clamp((ctx.frame - startFrame + 1) / drawFrames, 0, 1);
  const scale = Math.min(ctx.width, ctx.height) / 1080;
  const xRatio = clamp(number(p.marker_x_ratio, 0.61), 0, 1);
  const yRatio = clamp(number(p.marker_y_ratio, 0.55), 0, 1);
  const length = Math.max(24, Math.min(ctx.width * number(p.marker_length_ratio, 0.11), ctx.height * 0.22));
  const thickness = Math.max(3, number(p.marker_width_px, 18) * scale);
  const roughness = Math.max(0, number(p.marker_roughness_px, 1.3) * scale);
  const x0 = ctx.width * xRatio - length * 0.5;
  const y0 = ctx.height * yRatio;
  const segments = 120;
  const top = [];
  const bottom = [];
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const profile = 0.56 + 0.44 * Math.pow(Math.sin(Math.PI * t), 0.78);
    const half = Math.max(1.1, thickness * profile * 0.5);
    const noise = Math.sin((i + 1) * 12.9898 + 78.233) * 43758.5453;
    const jitter = (noise - Math.floor(noise)) * 2 - 1;
    const edge = Math.min(roughness, half * 0.3) * jitter;
    const middle = y0 - length * 0.035 * t + Math.sin(t * Math.PI * 1.6 + 0.4) * thickness * 0.12;
    const x = x0 + length * t;
    top.push([x, middle - half + edge]);
    bottom.push([x, middle + half - edge * 0.35]);
  }
  const exact = progress * segments;
  const low = Math.floor(exact);
  const fraction = exact - low;
  const visibleTop = top.slice(0, low + 1);
  const visibleBottom = bottom.slice(0, low + 1);
  if (fraction > 0 && low < segments) {
    visibleTop.push([top[low][0] + (top[low + 1][0] - top[low][0]) * fraction, top[low][1] + (top[low + 1][1] - top[low][1]) * fraction]);
    visibleBottom.push([bottom[low][0] + (bottom[low + 1][0] - bottom[low][0]) * fraction, bottom[low][1] + (bottom[low + 1][1] - bottom[low][1]) * fraction]);
  }
  const points = visibleTop.concat(visibleBottom.reverse());
  return [{
    kind: 'polygon',
    points: points,
    fill: markerColor,
    opacity: clamp(number(p.marker_opacity, 0.94), 0, 1)
  }];
}

function render(ctx) {
  const p = ctx.parameters || {};
  const w = ctx.width;
  const h = ctx.height;
  const frame = ctx.frame;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const scalar = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const paperColor = typeof p.paper_color === "string" ? p.paper_color : "#F4EFE6";
  const lightColor = typeof p.paper_light_color === "string" ? p.paper_light_color : "#FFFDF8";
  const markerColor = typeof p.marker_color === "string" ? p.marker_color : "#C9822B";
  const drawFrames = clamp(Math.round(scalar(p.marker_draw_frames, 10)), 8, 12);
  const settleFrame = Math.max(0, Math.round(scalar(p.title_settle_frame, 18)));
  const delayFrames = clamp(Math.round(scalar(p.marker_start_delay_frames, 6)), 4, 8);
  const centerRatio = clamp(scalar(p.marker_center_x_ratio, 0.6), 0.2, 0.8);
  const yRatio = clamp(scalar(p.marker_y_ratio, 0.545), 0.35, 0.75);
  const lengthRatio = clamp(scalar(p.marker_length_ratio, 0.105), 0.06, 0.18);
  const halfWidthRatio = clamp(scalar(p.marker_half_width_ratio, 0.035), 0.02, 0.055);
  const lightOpacity = clamp(scalar(p.paper_light_opacity, 0.22), 0.08, 0.35);
  const commands = [
    { kind: "rect", x: 0, y: 0, width: w, height: h, fill: paperColor }
  ];
  const time = Number.isFinite(ctx.time) ? ctx.time : frame / Math.max(1, scalar(ctx.fps, 30));
  const phase = time * Math.PI * 0.55;
  const lightX = w * (0.46 + 0.045 * Math.sin(phase));
  const lightY = h * (0.31 + 0.025 * Math.cos(phase * 0.83));
  commands.push({
    kind: "ellipse",
    x: lightX - w * 0.625,
    y: lightY - h * 0.55,
    width: w * 1.25,
    height: h * 1.1,
    fill: lightColor,
    opacity: lightOpacity
  });
  const markerStart = settleFrame + delayFrames;
  const rawProgress = clamp((frame - markerStart) / drawFrames, 0, 1);
  if (rawProgress > 0) {
    const progress = 1 - Math.pow(1 - rawProgress, 2.2);
    const length = w * lengthRatio;
    const left = w * centerRatio - length * 0.5;
    const baseY = h * yRatio;
    const segments = 48;
    const samples = [];
    for (let i = 0; i < segments; i += 1) {
      const t = i / segments;
      if (t < progress - 0.000001) samples.push(t);
    }
    samples.push(progress);
    const top = [];
    const bottom = [];
    for (let i = 0; i < samples.length; i += 1) {
      const t = samples[i];
      const x = left + t * length;
      const envelope = 0.58 + 0.42 * Math.pow(Math.sin(Math.PI * t), 0.72);
      const halfWidth = length * halfWidthRatio * envelope * (1 + 0.055 * Math.sin(t * segments * 1.37));
      const roughness = (Math.sin(t * segments * 2.13 + 0.7) * 0.9 + Math.sin(t * segments * 4.71 + 1.4) * 0.4) * Math.max(0.75, length * 0.0045);
      const centerY = baseY - t * length * 0.012 + Math.sin(t * 5.7 + 0.35) * length * 0.003;
      top.push([x, centerY - halfWidth + roughness]);
      bottom.push([x, centerY + halfWidth + roughness * 0.65]);
    }
    bottom.reverse();
    commands.push({
      kind: "polygon",
      points: top.concat(bottom),
      fill: markerColor,
      opacity: 0.94
    });
  }
  return commands;
}

